// Sample backend response. Display icons and colours are data, not selected by managers.
const backendPresentation={shipment:{icon:'🎁',milestone:'₹',achieved:'✓',timeIcon:'◷',dateIcon:'▦',detailsIcon:'›',tint:'#e5f3ff'},attendance:{icon:'📅',milestone:'₹',achieved:'✓',timeIcon:'◷',dateIcon:'▦',detailsIcon:'›',tint:'#fff0f4'}};
const entityValues={'User Type':['Full-time','Part-time'],Center:['BLR-HSR','BLR-Whitefield'],City:['Bangalore','Hyderabad'],'Entity ID':['RDR-1041','RDR-1042','RDR-1043']};
const previewEntity={'User Type':'Full-time',Center:'BLR-HSR',City:'Bangalore','Entity ID':'RDR-1041'};
const demoNow=new Date('2026-10-25T18:00:00+05:30');
let role='manager',programEdit=null,entityTab='active',nextProgramId=10;
fields.forEach(f=>{f.valueColumn='field_value';f.filterColumns=f.keys.map(k=>({key:k,column:k,label:keyNames[k],values:keys[k]}))});
fields[0].valueColumn='key_value';fields[0].sql=fields[0].sql.replace('shipment_type,','shipment_type AS field_filter1,').replace('AS field_value','AS key_value');fields[0].filterColumns[0].column='field_filter1';
configs.forEach((c,i)=>c.presentation=structuredClone(i===1?backendPresentation.attendance:backendPresentation.shipment));
const schemaFor=c=>({primary:c.primary,others:[...c.others],payout:c.payout,presentation:structuredClone(c.presentation||backendPresentation.shipment)});
function blankProgram(type=0){const c=configs[type];const payoutType=c.payouts[0];return {id:null,type,name:'',start:'2026-10-07',end:'2026-10-31',evaluation:'Daily',payoutType,behaviour:(payoutType==='Lump Sum'?c.lumpMatrix:c.variableMatrix)[0],entityFilters:{},keyFilters:{},fieldFilters:{},rows:c.primary==='attendance'?[{targets:{attendance:20},reward:1000},{targets:{attendance:24},reward:2000},{targets:{attendance:26},reward:3000}]:[{targets:{[c.primary]:50},reward:600},{targets:{[c.primary]:60},reward:700},{targets:{[c.primary]:70},reward:800}],status:'Draft',...schemaFor(c),metrics:{shipments:65,attendance:25,hours:8.5}}}
let programs=[];
function seed(){let a=blankProgram();a.id=1;a.name='Diwali Incentive';a.status='Live';a.rows=[50,60,70,80,90].map((v,i)=>({targets:{shipments:v},reward:600+i*100}));a.entityFilters={City:['Bangalore']};a.keyFilters={shipment_type:['COD','Prepaid']};a.fieldFilters={hours:{op:'>=',value:8}};programs.push(a);let b=structuredClone(a);b.id=2;b.name='Daily Shipment Incentive';b.payoutType='Variable';b.behaviour='all';b.metrics.shipments=75;b.rows.forEach((r,i)=>r.reward=i+2);programs.push(b);let c=structuredClone(b);c.id=3;c.name='Tiered Shipment Incentive';c.behaviour='tiered';programs.push(c);let d=blankProgram(1);d.id=4;d.name='Attendance Champion';d.metrics.shipments=550;d.status='Live';d.evaluation='Monthly';d.start='2026-10-01';d.end='2026-10-31';d.rows=[{targets:{attendance:20,shipments:400},reward:1000},{targets:{attendance:24,shipments:500},reward:2000},{targets:{attendance:26,shipments:600},reward:3000}];programs.push(d)}seed();
const oldRender=render,oldBind=bind;
function navRole(){let box=document.getElementById('roleSwitch');if(!box){box=document.createElement('div');box.id='roleSwitch';box.className='role-switch';document.querySelector('.brand').after(box)}box.innerHTML='<label for="role">USER TYPE</label><select id="role"><option value="admin">Admin</option><option value="manager">Manager</option><option value="entity">Entity</option></select>';document.getElementById('role').value=role;document.getElementById('role').onchange=e=>{role=e.target.value;currentView=role==='admin'?'registry':role;render()};document.querySelectorAll('[data-nav]').forEach(b=>b.hidden=role!=='admin');document.querySelector('.admin').innerHTML=esc(role[0].toUpperCase()+role.slice(1))+' workspace<small>Delivery · Rider</small>'}
render=function(){navRole();if(role==='admin'){oldRender();return}document.getElementById('breadcrumb').textContent=role==='manager'?'Manager / Incentive programs':'Entity / Incentives';document.getElementById('app').innerHTML=role==='manager'?(programEdit?managerForm():managerList()):entityView();if(role==='manager')bindManager();else bindEntity()};
bind=function(){oldBind()};
const currency=n=>'₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2});
const fieldUnit=id=>id==='shipments'?'shipment':id==='attendance'?'day':id==='hours'?'hour':(fby(id)?.kind==='Percentage'?'percentage point':'unit');
function programBehavior(p){return p.payoutType==='Lump Sum'?lumpNames[p.behaviour]:names[p.behaviour]}
function managerList(){return `<div class="titlebar"><h1>Incentive programs</h1><button class="button primary" id="createProgram">+ Create incentive</button></div>${context()}<section class="panel"><div class="panel-head"><h2>Programs <span class="badge">${programs.length}</span></h2></div><div class="tablewrap"><table><thead><tr><th>NAME</th><th>TYPE / EVALUATION</th><th>PROGRAM DATES</th><th>PAYOUT</th><th>STATUS</th><th></th></tr></thead><tbody>${programs.map(p=>`<tr class="program-row"><td><strong>${esc(p.name)}</strong></td><td>${esc(configs[p.type]?.name||'Incentive')}<small>${p.evaluation}</small></td><td class="nowrap">${dateLabel(p.start)} – ${dateLabel(p.end)}</td><td>${p.payoutType}<small>${esc(programBehavior(p))}</small></td><td><span class="tag ${p.status==='Live'?'status-live':'status-draft'}">${p.status}</span></td><td><button class="link" data-edit-program="${p.id}">${p.status==='Draft'?'Edit':'Open'}</button></td></tr>`).join('')}</tbody></table></div></section><p class="footer">Sample prototype · Programs and configurations are shared across user types for this page session.</p>`}
function dateLabel(s){return new Date(s+'T00:00:00+05:30').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Kolkata'})}
function selectedOptions(values,value){return values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}
function filterChoices(list,values,selectedValues,id,kind){return `<div class="choices">${values.map(v=>`<label class="choice"><input type="checkbox" data-filter-kind="${kind}" data-filter-id="${esc(id)}" value="${esc(v)}" ${selectedValues.includes(v)?'checked':''}>${esc(v)}</label>`).join('')}</div>`}
function managerForm(){const p=programEdit,c=configs[p.type];const targetIds=[c.primary,...c.others];const opts=p.payoutType==='Lump Sum'?c.lumpMatrix:c.variableMatrix;return `<div class="titlebar"><div><button class="link" id="backPrograms">Programs</button><h1 style="margin-top:10px">${p.id?'Incentive program':'Create incentive'}</h1></div><span class="badge">Delivery / Rider</span></div><div class="split"><div><section class="panel"><div class="panel-head"><h2><span class="section-number">01</span> Program</h2></div><div class="panel-body"><div class="group"><label for="pName" class="label">Incentive Name</label><input type="text" id="pName" data-program="name" value="${esc(p.name)}" placeholder="e.g. Diwali Shipment Incentive"></div><div class="grid"><div class="group"><label for="pType" class="label">Incentive Type ${info('Loads the fields, filters and payout options saved by the Admin.')}</label><select id="pType">${configs.map((x,i)=>`<option value="${i}" ${i===p.type?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="group"><label for="pEvaluation" class="label">Evaluation Period ${info('Daily, Weekly or Monthly targets restart for each period. Custom uses the program start and end dates.')}</label><select id="pEvaluation" data-program="evaluation">${selectedOptions(['Daily','Weekly','Monthly','Custom'],p.evaluation)}</select></div></div><div class="grid"><div><label class="label" for="pStart">Start Date</label><input type="date" id="pStart" data-program="start" value="${p.start}"></div><div><label class="label" for="pEnd">End Date</label><input type="date" id="pEnd" data-program="end" value="${p.end}"></div></div></div></section><section class="panel"><div class="panel-head"><h2><span class="section-number">02</span> Participants & filters</h2></div><div class="panel-body">${filterBuilder(p,'entityFilters')}${filterBuilder(p,'fieldFilters')}</div></section><section class="panel"><div class="panel-head"><h2><span class="section-number">03</span> Target matrix & payout</h2></div><div class="panel-body"><div class="grid"><div class="group"><label class="label" for="pPayout">Payout Type</label><select id="pPayout">${selectedOptions(c.payouts,p.payoutType)}</select></div><div class="group"><label class="label" for="pBehavior">Matrix Behaviour</label><select id="pBehavior">${opts.map(x=>`<option value="${x}" ${x===p.behaviour?'selected':''}>${esc(p.payoutType==='Lump Sum'?lumpNames[x]:names[x])}</option>`).join('')}</select></div></div><div class="subtle group">Primary Field: <strong>${esc(fname(c.primary))}</strong>${p.payoutType==='Variable'?`<br>Payout Field: <strong>${esc(fname(c.payout))}</strong>`:''}</div><div class="tablewrap"><table class="matrix-edit"><thead><tr><th>SLAB</th>${targetIds.map(id=>`<th>${esc(fname(id))} ≥ ${info(id===c.primary?'Required target. This field moves the entity timeline.':'Optional additional target. All populated conditions in a row must be met.')}</th>`).join('')}<th>${p.payoutType==='Lump Sum'?'REWARD ₹':'RATE ₹ / '+esc(fieldUnit(c.payout)).toUpperCase()}</th><th></th></tr></thead><tbody>${p.rows.map((r,i)=>`<tr><td>${i+1}</td>${targetIds.map(id=>`<td><input type="number" min="0" step="any" data-target-row="${i}" data-target-id="${id}" value="${r.targets[id]??''}" placeholder="${id===c.primary?'Target':'Optional'}" aria-label="Slab ${i+1} ${esc(fname(id))}"></td>`).join('')}<td><input type="number" min="0" step="any" data-reward="${i}" value="${r.reward}" aria-label="Slab ${i+1} reward"></td><td><button class="link" data-remove-row="${i}" aria-label="Remove slab ${i+1}" ${p.rows.length<=1?'disabled':''}>×</button></td></tr>`).join('')}</tbody></table></div><button class="link" id="addSlab" style="margin-top:15px">+ Add slab</button><div class="notice">${esc(formulaText(p))}</div></div></section><div class="form-actions"><span id="programErrors" class="error-text" role="alert"></span><div class="choices"><button class="button" id="saveProgramDraft">Save draft</button><button class="button primary" id="makeLive">Make live</button></div></div></div><section class="panel summary manager-preview"><div class="panel-head"><h2>Entity display</h2></div><div class="panel-body"><div class="icon-preview"><span style="font-size:30px">${p.presentation.icon}</span><strong id="previewName">${esc(p.name||'Incentive name')}</strong></div><dl><dt>PRIMARY FIELD</dt><dd>${esc(fname(c.primary))}</dd><dt>PERIOD</dt><dd>${p.evaluation}</dd><dt>PAYOUT</dt><dd>${p.payoutType}<br>${esc(programBehavior(p))}</dd><dt>REWARD PLACEMENT</dt><dd>${p.behaviour==='tiered'?'Between milestones':'Above milestones'}</dd></dl><p class="backend-note">Icons are supplied by the sample backend configuration.</p></div></section></div>`}
function formulaText(p){if(p.payoutType==='Lump Sum')return p.behaviour==='tiered'?'Payout = sum of rewards for all achieved slabs.':'Payout = reward for the highest slab where all targets are met.';if(p.behaviour==='all')return `Payout = highest achieved rate × ${fname(p.payout)}.`;if(p.behaviour==='only')return 'Payout = highest achieved rate × quantity above that slab’s starting boundary.';return 'Payout = sum of each slab’s rate × quantity above its boundary, up to the next boundary.'}
function programValidation(p){const c=configs[p.type];if(!p.name.trim())return 'Enter an incentive name.';if(!p.start||!p.end||p.start>p.end)return 'Enter valid start and end dates.';if(!c.payouts.includes(p.payoutType))return 'Select an available payout type.';if(!(p.payoutType==='Lump Sum'?c.lumpMatrix:c.variableMatrix).includes(p.behaviour))return 'Select an available matrix behaviour.';if(!p.rows.length)return 'Add at least one slab.';let last=-1;const previous={};for(const r of p.rows){const n=r.targets[c.primary];if(n==null||!Number.isFinite(n)||n<=last||n<0)return 'Primary targets must be non-negative and increase for each slab.';last=n;if(!Number.isFinite(r.reward)||r.reward<0)return 'Enter a non-negative reward for every slab.';if(Object.values(r.targets).some(v=>!Number.isFinite(v)||v<0))return 'Enter non-negative target values.';for(const [id,v] of Object.entries(r.targets)){if(previous[id]!=null&&v<previous[id])return 'Additional field targets must not decrease in later slabs.';previous[id]=v}}return ''}
function saveProgram(status){const p=programEdit;const error=programValidation(p);if(error){document.getElementById('programErrors').textContent=error;return false}p.status=status;p.name=p.name.trim();if(!p.id)p.id=nextProgramId++;const idx=programs.findIndex(x=>x.id===p.id);const saved=structuredClone(p);if(idx>=0)programs[idx]=saved;else programs.push(saved);programEdit=null;render();toast(status==='Live'?'Incentive is live in the entity preview.':'Draft saved for this session.');return true}
function bindManager(){document.getElementById('createProgram')?.addEventListener('click',()=>{programEdit=blankProgram();render()});document.querySelectorAll('[data-edit-program]').forEach(b=>b.onclick=()=>{programEdit=structuredClone(programs.find(p=>p.id===Number(b.dataset.editProgram)));render()});document.getElementById('backPrograms')?.addEventListener('click',()=>{programEdit=null;render()});document.querySelectorAll('[data-program]').forEach(el=>el.oninput=()=>{programEdit[el.dataset.program]=el.value;if(el.dataset.program==='name')document.getElementById('previewName').textContent=el.value||'Incentive name'});document.getElementById('pType')?.addEventListener('change',e=>{const old=programEdit;programEdit={...blankProgram(Number(e.target.value)),id:old.id,name:old.name,start:old.start,end:old.end,evaluation:old.evaluation,status:old.status};render()});document.querySelectorAll('[data-filter-kind]').forEach(el=>el.onchange=()=>{const kind=el.dataset.filterKind,id=el.dataset.filterId;programEdit[kind][id]=[...document.querySelectorAll('[data-filter-kind]')].filter(x=>x.dataset.filterKind===kind&&x.dataset.filterId===id&&x.checked).map(x=>x.value)});document.querySelectorAll('[data-condition]').forEach(el=>el.oninput=()=>{const id=el.dataset.condition;if(el.value===''){delete programEdit.fieldFilters[id];return}programEdit.fieldFilters[id]={value:Number(el.value),op:document.querySelector(`[data-condition-op="${id}"]`).value}});document.querySelectorAll('[data-condition-op]').forEach(el=>el.onchange=()=>{if(programEdit.fieldFilters[el.dataset.conditionOp])programEdit.fieldFilters[el.dataset.conditionOp].op=el.value});document.getElementById('pPayout')?.addEventListener('change',e=>{programEdit.payoutType=e.target.value;programEdit.behaviour=(e.target.value==='Lump Sum'?configs[programEdit.type].lumpMatrix:configs[programEdit.type].variableMatrix)[0];render()});document.getElementById('pBehavior')?.addEventListener('change',e=>{programEdit.behaviour=e.target.value;render()});document.querySelectorAll('[data-target-row]').forEach(el=>el.oninput=()=>{const r=programEdit.rows[Number(el.dataset.targetRow)];if(el.value==='')delete r.targets[el.dataset.targetId];else r.targets[el.dataset.targetId]=Number(el.value)});document.querySelectorAll('[data-reward]').forEach(el=>el.oninput=()=>programEdit.rows[Number(el.dataset.reward)].reward=el.value===''?NaN:Number(el.value));document.querySelectorAll('[data-remove-row]').forEach(el=>el.onclick=()=>{programEdit.rows.splice(Number(el.dataset.removeRow),1);render()});document.getElementById('addSlab')?.addEventListener('click',()=>{const p=programEdit,last=p.rows.at(-1);p.rows.push({targets:{[p.primary]:(last?.targets[p.primary]||0)+10},reward:0});render()});document.getElementById('saveProgramDraft')?.addEventListener('click',()=>saveProgram('Draft'));document.getElementById('makeLive')?.addEventListener('click',()=>saveProgram('Live'))}
function compare(n,op,v){return op==='>='?n>=v:op==='>'?n>v:op==='<='?n<=v:op==='<'?n<v:n===v}
function calculate(p){const eligible=Object.entries(p.fieldFilters).every(([id,c])=>compare(Number(p.metrics[id]||0),c.op,c.value));const matches=p.rows.map(r=>eligible&&Object.entries(r.targets).every(([id,n])=>(p.metrics[id]||0)>=n));const highest=matches.lastIndexOf(true);const contributions=p.rows.map((r,i)=>{if(!matches[i])return 0;if(p.payoutType==='Lump Sum')return p.behaviour==='tiered'||i===highest?r.reward:0;if(p.behaviour==='all')return i===highest?r.reward*(p.metrics[p.payout]||0):0;if(p.behaviour==='only'&&i!==highest)return 0;const upper=p.rows[i+1]?.targets[p.primary]??Infinity;return Math.max(0,Math.min(p.metrics[p.payout]||0,upper)-r.targets[p.primary])*r.reward});return {eligible,matches,highest,contributions,total:contributions.reduce((a,b)=>a+b,0)}}
function period(p){const start=new Date(p.start+'T00:00:00+05:30'),end=p.end?new Date(p.end+'T23:59:59+05:30'):new Date(8640000000000000);let a=new Date(demoNow),b=new Date(demoNow);const today='2026-10-25';if(p.evaluation==='Daily'){a=new Date(today+'T00:00:00+05:30');b=new Date(today+'T23:59:59+05:30')}else if(p.evaluation==='Weekly'){a=new Date(+start+Math.max(0,Math.floor((demoNow-start)/(7*86400000)))*7*86400000);b=new Date(+a+7*86400000-1)}else if(p.evaluation==='Monthly'){a=new Date('2026-10-01T00:00:00+05:30');b=new Date('2026-10-31T23:59:59+05:30')}else{a=start;b=end}return {start:new Date(Math.max(a,start)),end:new Date(Math.min(b,end)),programStart:start,programEnd:end}}
function timeLeft(p){if(!p.end&&p.evaluation==='Custom')return 'Ongoing';const q=period(p);if(demoNow<q.programStart)return 'Starts '+dateLabel(p.start);if(demoNow>q.programEnd)return 'Completed';const hours=Math.ceil((q.end-demoNow)/3600000);return hours>24?Math.ceil(hours/24)+' days left':Math.max(0,hours)+' hours left'}
function isParticipant(p){return Object.entries(p.entityFilters).every(([k,v])=>!v.length||v.includes(previewEntity[k]))}
function rewardText(p,r){return p.payoutType==='Lump Sum'?currency(r.reward):currency(r.reward)+'/'+fieldUnit(p.payout)}
function nextText(p,result){if(!result.eligible)return 'Meet the eligibility conditions to earn this incentive.';const next=p.rows[result.highest+1];if(!next)return 'Highest target achieved';const missing=Object.entries(next.targets).filter(([id,v])=>(p.metrics[id]||0)<v).map(([id,v])=>`${Number((v-(p.metrics[id]||0)).toFixed(2))} more ${fname(id).toLowerCase()}`);if(!missing.length)return 'Target achieved';return 'Complete '+missing.join(' and ')+' to '+(p.behaviour==='tiered'&&p.payoutType==='Variable'?'unlock '+rewardText(p,next)+' for the next portion.':'earn '+rewardText(p,next)+'.')}
function timeline(p,r){const n=p.rows.length,positions=p.rows.map((_,i)=>n===1?50:10+i*80/(n-1));const value=period(p).programStart>demoNow?0:(p.metrics[p.primary]||0);let progress=0;const thresholds=p.rows.map(x=>x.targets[p.primary]);if(value<thresholds[0])progress=thresholds[0]?positions[0]*value/thresholds[0]:positions[0];else{let i=thresholds.findLastIndex(v=>value>=v);progress=i===n-1?positions[i]:positions[i]+(positions[i+1]-positions[i])*(value-thresholds[i])/(thresholds[i+1]-thresholds[i]);}return `<div class="timeline-scroll"><div class="timeline" style="min-width:${Math.max(320,n*76)}px"><div class="track"><div class="track-fill" style="width:${Math.max(0,Math.min(100,progress))}%"></div></div>${p.rows.map((row,i)=>{const applies=p.behaviour==='tiered'?(p.payoutType==='Variable'?r.contributions[i]>0:r.matches[i]):i===r.highest;const replaced=r.matches[i]&&!applies;let rewardPosition=positions[i];if(p.behaviour==='tiered')rewardPosition=p.payoutType==='Variable'?(positions[i]+(positions[i+1]??100))/2:((positions[i-1]??0)+positions[i])/2;return `<span class="reward-label ${applies?'earned':''} ${replaced?'replaced':''}" style="left:${rewardPosition}%">${esc(rewardText(p,row))}</span><span class="milestone" style="left:${positions[i]}%"><span class="coin ${applies?'achieved':''}">${applies?p.presentation.achieved:p.presentation.milestone}</span><span class="milestone-value">${row.targets[p.primary]}${p.primary==='attendance'?' days':''}</span></span>`}).join('')}</div></div>`}
function breakdown(p,r){if(!r.total)return 'No reward earned for this evaluation period.';if(p.payoutType==='Lump Sum')return p.behaviour==='tiered'?r.contributions.filter(v=>v>0).map(currency).join(' + '):'Highest achieved slab';if(p.behaviour==='all')return `${p.metrics[p.payout]} × ${currency(p.rows[r.highest].reward)} per ${fieldUnit(p.payout)}`;return r.contributions.map((v,i)=>v>0?`${Number((v/p.rows[i].reward).toFixed(2))} × ${currency(p.rows[i].reward)}`:null).filter(Boolean).join(' + ')}
function entityCard(p){const r=calculate(p);const upcoming=period(p).programStart>demoNow;return `<article class="incentive-card" style="--card-tint:${p.presentation.tint}"><button class="inc-header" data-details="${p.id}" aria-label="View ${esc(p.name)} details"><span class="inc-icon">${p.presentation.icon}</span><span class="inc-head-copy"><span class="inc-title">${esc(p.name)}</span><span class="inc-meta"><span>${p.presentation.timeIcon} ${timeLeft(p)}</span><span>${p.presentation.dateIcon} ${dateLabel(p.start)} – ${dateLabel(p.end)}</span></span></span><span class="inc-chevron">${p.presentation.detailsIcon}</span></button><div class="inc-body"><p class="next-target">${upcoming?'Targets for the upcoming incentive':esc(nextText(p,r))}</p>${timeline(p,upcoming?{...r,matches:p.rows.map(()=>false),contributions:p.rows.map(()=>0),highest:-1}:r)}<div class="performance">${esc(fname(p.primary))}: <strong>${upcoming?0:p.metrics[p.primary]||0}</strong></div><div class="earning"><span>Earnings</span><strong>${currency(upcoming?0:r.total)}</strong><small>${upcoming?'Program has not started.':esc(breakdown(p,r))}</small></div><div class="updated">${p.evaluation} evaluation · Sample progress</div></div></article>`}
function entityView(){const visible=programs.filter(p=>p.status==='Live'&&isParticipant(p));const active=visible.filter(p=>period(p).programStart<=demoNow&&period(p).programEnd>=demoNow);const upcoming=visible.filter(p=>period(p).programStart>demoNow);const completed=visible.filter(p=>period(p).programEnd<demoNow);const editable=visible[0];return `<div class="titlebar"><h1>Entity preview</h1><span class="badge">RDR-1041 · Bangalore</span></div><div class="sample-strip"><span class="quiet">Sample clock: 25 Oct 2026, 6:00 PM IST</span></div><div class="entity-layout"><div class="entity-mobile"><div class="entity-heading">Incentives</div><div class="entity-tabs"><button data-entity-tab="active" class="${entityTab==='active'?'selected':''}">Incentives</button><button data-entity-tab="completed" class="${entityTab==='completed'?'selected':''}">Completed</button></div>${(entityTab==='active'?active:completed).map(entityCard).join('')||'<div class="empty">No incentives to show.</div>'}${entityTab==='active'&&upcoming.length?'<h2 style="margin:25px 0 15px">Upcoming Incentives</h2>'+upcoming.map(entityCard).join(''):''}</div><section class="panel sample-panel"><div class="panel-head"><h2>Sample performance ${info('Preview controls only. In the live product, progress, earnings and icons come from the backend.')}</h2></div><div class="panel-body"><div class="group"><label class="label" for="sampleProgram">Incentive</label><select id="sampleProgram">${visible.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div id="sampleInputs">${editable?sampleInputs(editable):'<span class="quiet">Make a program live to preview it.</span>'}</div></div></section></div><p class="footer">Sample prototype · Changes last for this page session.</p>`}
function sampleInputs(p){const ids=[...new Set([p.primary,...p.others,p.payout,...ensureRules(p).fieldFilters.map(r=>r.field)])];return ids.map(id=>`<label class="label" for="metric-${id}">${esc(fname(id))}</label><input id="metric-${id}" type="number" min="0" step="any" data-metric="${id}" value="${p.metrics[id]||0}">`).join('')+'<button class="button primary" id="applyMetrics">Update preview</button><p class="quiet">Values represent activity after the program’s filters.</p>'}
function bindEntity(){document.querySelectorAll('[data-details]').forEach(b=>b.onclick=()=>openDetails(Number(b.dataset.details)));document.querySelectorAll('[data-entity-tab]').forEach(b=>b.onclick=()=>{entityTab=b.dataset.entityTab;render()});document.getElementById('sampleProgram')?.addEventListener('change',e=>{document.getElementById('sampleInputs').innerHTML=sampleInputs(programs.find(p=>p.id===Number(e.target.value)));bindMetrics()});bindMetrics()}
function bindMetrics(){document.getElementById('applyMetrics')?.addEventListener('click',()=>{const id=Number(document.getElementById('sampleProgram').value),p=programs.find(x=>x.id===id);const inputs=[...document.querySelectorAll('[data-metric]')];if(inputs.some(x=>x.value===''||!Number.isFinite(Number(x.value))||Number(x.value)<0)){toast('Enter non-negative sample values.');return}inputs.forEach(x=>p.metrics[x.dataset.metric]=Number(x.value));render();document.getElementById('sampleProgram').value=id;document.getElementById('sampleInputs').innerHTML=sampleInputs(p);bindMetrics()})}
function openDetails(id){const p=programs.find(x=>x.id===id),r=calculate(p);const d=document.getElementById('fieldDialog');d.classList.add('details-dialog');d.innerHTML=`<div class="panel-head"><h2>${esc(p.name)}</h2><button class="close" id="closeDetails" aria-label="Close details">×</button></div><div class="dialogbody"><h2>Conditions</h2><ul class="details-list"><li>${p.evaluation} evaluation. ${dateLabel(p.start)} – ${dateLabel(p.end)}.</li><li>${esc(formulaText(p))}</li>${detailsFilterRules(p)}</ul><h2 style="margin:25px 0 12px">Incentive stages</h2><div class="panel" style="padding:0 18px">${p.rows.map((row,i)=>{const applies=p.behaviour==='tiered'?(p.payoutType==='Variable'?r.contributions[i]>0:r.matches[i]):i===r.highest;return `<div class="stage-row ${r.matches[i]&&!applies?'replaced':''}"><span class="coin ${applies?'achieved':''}">${applies?p.presentation.achieved:p.presentation.milestone}</span><div><${applies?'strong':'span'}>${esc(rewardText(p,row))}</${applies?'strong':'span'}><small>${Object.entries(row.targets).map(([id,v])=>`${esc(fname(id))} ≥ ${v}`).join(' AND ')}</small>${p.payoutType==='Variable'&&p.behaviour!=='all'?`<small>Paid on the quantity above ${row.targets[p.primary]}${p.rows[i+1]?' up to '+p.rows[i+1].targets[p.primary]:''}.</small>`:''}</div></div>`}).join('')}</div><div class="earning"><span>Earnings</span><strong>${currency(period(p).programStart>demoNow?0:r.total)}</strong></div></div>`;d.showModal();document.getElementById('closeDetails').onclick=()=>d.close()}
// Admin query output mapping: value and optional filter columns are configured together.
let fieldDraft;
openField=function(index){editing=index;checkedSql=false;fieldDraft=index>=0?structuredClone(fields[index]):{id:'field-'+Date.now(),name:'',kind:'Float',unit:'Numeric value',keys:[],valueColumn:'key_value',filterColumns:[],sql:'SELECT\n  DATE(closed_at) AS date,\n  rider_id AS entity_id,\n  shipment_type AS field_filter1,\n  COUNT(DISTINCT shipment_id) AS key_value\nFROM shipment_activity\nGROUP BY 1, 2, 3',sample:[42,58,36]};if(index<0)fieldDraft.filterColumns=[{key:fieldDraft.id+':field_filter1',column:'field_filter1',label:'Shipment Type',dataType:'Character',values:['COD','Prepaid']}];const f=fieldDraft,d=document.getElementById('fieldDialog');d.classList.remove('details-dialog');d.innerHTML=`<div class="panel-head"><h2 id="dialogTitle">${index<0?'Create field':esc(f.name)}</h2><button class="close" id="closeField" aria-label="Close">×</button></div><div class="dialogbody"><div class="grid group"><div><label class="label" for="fieldName">Field name</label><input type="text" id="fieldName" value="${esc(f.name)}"></div><div><label class="label" for="fieldKind">Value type</label><select id="fieldKind">${selectedOptions(['Integer','Float','Percentage'],f.kind)}</select></div></div><div class="group"><label class="label" for="sql">SQL query ${info('Return Date, Entity ID, a value column and optional filter columns. For example, key_value and field_filter1.')}</label><textarea id="sql" spellcheck="false">${esc(f.sql)}</textarea></div><div class="group"><label class="label" for="valueColumn">Value column ${info('The SQL output column containing the numeric value used for targets and payouts.')}</label><input type="text" id="valueColumn" value="${esc(f.valueColumn)}"></div><div class="group"><span class="label">Filter columns ${info('Capture a query output such as field_filter1, give it a name, and set its data type. Comparison values are entered when configuring the incentive.')}</span><div class="maprow quiet"><span>SQL output column</span><span>Filter name</span><span>Data type</span><span></span></div><div id="filterMapping"></div><button class="link" id="addFilterColumn" style="margin-top:14px">+ Add filter column</button></div><button class="button" id="checkQuery">Check required columns</button>${info('Prototype checks output column names only. SQL execution and coverage checks are not connected.')}<div id="queryResult" role="status"></div><div class="group" style="margin-top:22px"><span class="label">Sample output</span><div class="tablewrap" id="fieldSample"></div></div><div class="savebar"><button class="button" id="cancelField">Cancel</button><button class="button primary" id="saveField">Save field</button></div></div>`;d.showModal();renderMappings();document.getElementById('closeField').onclick=document.getElementById('cancelField').onclick=()=>d.close();['sql','valueColumn'].forEach(id=>document.getElementById(id).oninput=()=>{checkedSql=false;document.getElementById('queryResult').innerHTML=''});document.getElementById('addFilterColumn').onclick=()=>{captureMappings();const n=fieldDraft.filterColumns.length+1;fieldDraft.filterColumns.push({key:fieldDraft.id+':field_filter'+n,column:'field_filter'+n,label:'',dataType:'Character',values:[]});checkedSql=false;renderMappings()};document.getElementById('checkQuery').onclick=checkQuery;document.getElementById('saveField').onclick=()=>{if(!document.getElementById('fieldName').value.trim()){toast('Enter a field name.');return}captureMappings();if(fieldDraft.filterColumns.some(x=>!x.label.trim())){toast('Enter a name for each filter column.');return}if(!checkQuery())return;f.name=document.getElementById('fieldName').value.trim();if(fields.some((x,i)=>i!==editing&&x.name.toLowerCase()===f.name.toLowerCase())){toast('A field with this name already exists.');return}f.kind=document.getElementById('fieldKind').value;f.valueColumn=document.getElementById('valueColumn').value.trim();f.sql=document.getElementById('sql').value;f.formula=f.formula||'SQL-defined field';f.keys=f.filterColumns.map(x=>x.key);f.filterColumns.forEach(x=>{keys[x.key]=x.values||[];keyNames[x.key]=x.label;keyHelp[x.key]='Values from '+x.column+' in '+f.name+'.'});if(editing>=0)fields[editing]=structuredClone(f);else fields.push(structuredClone(f));configs.forEach(c=>{const available=new Set([c.primary,...c.others,c.payout].flatMap(id=>fby(id)?.keys||[]));c.keyFilters=c.keyFilters.filter(k=>available.has(k))});draft=selected>=0?structuredClone(configs[selected]):draft;d.close();render();toast('Field and filter columns saved for this session.')}};
function captureMappings(){document.querySelectorAll('[data-map-column]').forEach(el=>{const i=Number(el.dataset.mapColumn),m=fieldDraft.filterColumns[i];m.column=el.value.trim();m.label=document.querySelector(`[data-map-label="${i}"]`).value.trim();m.dataType=document.querySelector(`[data-map-type="${i}"]`).value})}
function renderMappings(){document.getElementById('filterMapping').innerHTML=fieldDraft.filterColumns.map((m,i)=>`<div class="maprow"><input type="text" aria-label="Filter ${i+1} output column" data-map-column="${i}" value="${esc(m.column)}"><input type="text" aria-label="Filter ${i+1} name" data-map-label="${i}" value="${esc(m.label)}" placeholder="e.g. Shipment Type"><select aria-label="Filter ${i+1} data type" data-map-type="${i}">${selectedOptions(['Character','Integer','Float'],m.dataType||'Character')}</select><button class="link" data-remove-map="${i}" aria-label="Remove filter ${i+1}">×</button></div>`).join('');document.querySelectorAll('[data-map-column],[data-map-label],[data-map-type]').forEach(el=>el.oninput=()=>{checkedSql=false});document.querySelectorAll('[data-remove-map]').forEach(el=>el.onclick=()=>{captureMappings();fieldDraft.filterColumns.splice(Number(el.dataset.removeMap),1);checkedSql=false;renderMappings()});const f=fieldDraft;document.getElementById('fieldSample').innerHTML=`<table><thead><tr><th>date</th><th>entity_id</th><th>${esc(f.valueColumn)}</th>${f.filterColumns.map(m=>`<th>${esc(m.column)}</th>`).join('')}</tr></thead><tbody>${f.sample.map((v,i)=>`<tr><td>2026-10-06</td><td>RDR-${1041+i}</td><td>${v}</td>${f.filterColumns.map(m=>`<td>${esc(m.dataType==='Integer'?[10,15,20][i]:m.dataType==='Float'?[2.5,4.25,7.5][i]:(m.values?.[i%(m.values?.length||1)]||'Sample'))}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
checkQuery=function(){captureMappings();const sql=document.getElementById('sql').value.replace(/--[^\n]*/g,'').replace(/\/\*[\s\S]*?\*\//g,'');const projection=(sql.match(/\bselect\b([\s\S]*?)\bfrom\b/i)||[])[1]||'';const required=['date','entity_id',document.getElementById('valueColumn').value.trim(),...fieldDraft.filterColumns.map(x=>x.column)];if(required.some(k=>!/^\w+$/.test(k))||new Set(required).size!==required.length){document.getElementById('queryResult').innerHTML='<div class="notice error">Use unique output column names containing letters, numbers or underscores.</div>';checkedSql=false;return false}const missing=required.filter(k=>!new RegExp('(?:\\bas\\s+'+k+'\\b|(?:^|,)\\s*(?:\\w+\\.)?'+k+'\\s*(?:,|$))','i').test(projection));checkedSql=!missing.length;document.getElementById('queryResult').innerHTML=`<div class="notice ${checkedSql?'success':'error'}">${checkedSql?'Value and filter column names found. SQL execution and coverage are not checked.':'Missing output columns: '+esc(missing.join(', '))}</div>`;return checkedSql};
// Use the same dialog for hover help in all personas.
currentView='manager';
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_incentive_programs',description:'Read the sample incentive programs and calculated entity earnings for this session.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>programs.map(p=>({id:p.id,name:p.name,status:p.status,earnings:calculate(p).total}))})).catch(()=>{})}catch{}}
